/**
 * The typed tables of the arcaTenancy model, generated by IFC Data from the model. Do not edit: change the model and run `bun tools/typed.ts --write`.
 *
 * The boundaries that separate one customer's data from another's, and their hierarchy
 *
 * @module
 */
import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** A boundary that separates one customer's data from another's, in a hierarchy of boundaries */
export interface TenantRow {
  /** What identifies the tenant, made by the application when it is created */
  readonly tenantId: string;
  /** What the tenant is in the hierarchy */
  readonly kind: "platform" | "reseller" | "business" | "consumer_pool";
  /** The short name the tenant is addressed by, unique among tenants */
  readonly slug: string;
  /** The name the tenant is shown by */
  readonly displayName: string;
  /** The path of the tenant's parents from the root, kept by the operation that moves a tenant, so that a subtree is one query */
  readonly ancestry: string;
  /** Where the tenant is in its life */
  readonly status: "active" | "suspended" | "closed";
  /** How much of the platform the tenant has to itself */
  readonly isolation: "shared" | "dedicated";
  /** When the tenant was made */
  readonly createdAt: Timestamp;
  /** The organization the tenant is for; a pool of consumers has none */
  readonly organizationPartyId: string | null;
  /** The tenant this one is under; the root has none */
  readonly parentTenantId: string | null;
}

/** What an insert into tenant takes: what the database fills may be left out. */
export interface TenantInsert {
  readonly tenantId: string;
  readonly kind: "platform" | "reseller" | "business" | "consumer_pool";
  readonly slug: string;
  readonly displayName: string;
  readonly ancestry: string;
  readonly status: "active" | "suspended" | "closed";
  readonly isolation: "shared" | "dedicated";
  readonly createdAt: Timestamp;
  readonly organizationPartyId?: string | null;
  readonly parentTenantId?: string | null;
}

/** The key of a row of tenant. */
export type TenantKey = { readonly tenantId: string };

/** A boundary that separates one customer's data from another's, in a hierarchy of boundaries */
export const tenant = defineTable<TenantRow, TenantInsert, "tenant">({
  alias: "tenant",
  name: "tenant",
  columns: {
    tenantId: "tenant_id",
    kind: "kind",
    slug: "slug",
    displayName: "display_name",
    ancestry: "ancestry",
    status: "status",
    isolation: "isolation",
    createdAt: "created_at",
    organizationPartyId: "organization_party_id",
    parentTenantId: "parent_tenant_id",
  },
  primaryKey: ["tenantId"],
  foreignKeys: [
    { columns: ["organizationPartyId"], references: "organization", referencesColumns: ["partyId"] },
    { columns: ["parentTenantId"], references: "tenant", referencesColumns: ["tenantId"] },
  ],
});
